SELECT 'ct-blog-system', 'blog', 'Blog Posts', 'Blog articles, news, and updates', '[{"name":"excerpt","label":"Excerpt","type":"textarea","required":true,"placeholder":"A brief summary of the post...","helpText":"Shown on list pages and in search results","validation":{"maxLength":300},"sortOrder":1},{"name":"body","label":"Body","type":"richtext","required":true,"helpText":"The main content of the post (supports Markdown)","sortOrder":2},{"name":"featured_image","label":"Featured Image","type":"image","placeholder":"https://example.com/image.jpg","helpText":"Upload an image or paste a URL","sortOrder":3},{"name":"category","label":"Category","type":"select","options":[{"label":"General","value":"general"},{"label":"Tutorial","value":"tutorial"},{"label":"News","value":"news"},{"label":"Update","value":"update"},{"label":"Guide","value":"guide"}],"defaultValue":"general","sortOrder":4},{"name":"read_time","label":"Read Time (minutes)","type":"number","placeholder":"5","helpText":"Estimated reading time","validation":{"min":1,"max":120},"sortOrder":5}]', '{"hasDrafts":true,"hasTags":true,"hasSEO":true,"hasAuthor":true,"routePrefix":"/blog","listPageSize":12,"defaultSort":"published_at","defaultSortDirection":"desc","isPublic":true,"listTemplate":"blog-list","itemTemplate":"blog-item"}', 'article', 0, 1
