-- 2024-2025-progress-and-future-plans
INSERT INTO content_items (id, content_type_id, slug, title, status, fields, seo_title, seo_description, seo_image, author_id, published_at, created_at, updated_at)
SELECT 'import-blog-2024-2025-progress-and-future-plans', ct.id, '2024-2025-progress-and-future-plans', 'Exploring SvelteKit, Deno, and the Future of *Space', 'published', '{"excerpt":"Reflecting on a year and a half of learning SvelteKit and Deno, contributing to Deno Docs, spending time in Maine, and planning the future of *Space.","body":"<p>Over the past year and a half, I’ve immersed myself in <strong>Cloudflare</strong>,\n<strong>SvelteKit</strong>, and <strong>Deno</strong>, contributing to open-source projects, launching the\nMVP of <strong>AgapeVerse</strong> (an AI-powered poem generator), and laying the groundwork\nfor an ambitious vision: expanding *Space from a thriving online community into\na real-world, DAO-governed space. Along the way, life has also taken me to\nMaine, where I’ve been enjoying time with my new girlfriend.</p>\n<h2>Diving into Cloudflare, SvelteKit, and Deno</h2>\n<p>Building modern, high-performance applications has always been a passion of\nmine, and <strong>SvelteKit</strong> quickly became one of my favorite frameworks. Its\nsimplicity, efficiency, and reactivity make frontend development both enjoyable\nand productive. At the same time, <strong>Deno</strong>, a secure and modern runtime for\nJavaScript and TypeScript, stood out as a strong alternative to Node.js,\noffering built-in TypeScript support and a more secure default environment.</p>\n<p><strong>Cloudflare</strong> made it easy to launch professional web services quickly,\naffordably, and with an incredibly generous free tier—including powerful AI\ntools. After experimenting with Google App Engine, Vercel, AWS Amplify, and\nothers, I ultimately settled on <strong>Cloudflare</strong> as my go-to platform for web\ndeployment.</p>\n<p>In October 2024, I committed to building and releasing an MVP (Minimum Viable\nProduct) within a few months as a personal challenge. That project became\n<strong>AgapeVerse</strong>, an AI-powered &quot;love&quot; poem generator. Initially, I started with\n<strong>SvelteKit</strong> on <strong>Cloudflare</strong>, but when <strong>Deno 2</strong> was released, I saw an\nopportunity to shift to <strong>Deno Fresh</strong> and <strong>Deno Deploy</strong>. The timing couldn’t\nhave been better—I had already been keeping an eye on Deno, and this felt like\nthe right moment to make the switch. Along the way, I contributed a <strong>dark mode\nfeature</strong> to Deno’s official documentation, which you can check out here:<br><a href=\"https://github.com/denoland/docs/pull/1038\">https://github.com/denoland/docs/pull/1038</a>.</p>\n<h2>A Change of Scenery: Time in Maine</h2>\n<p>Amidst all the coding and planning, I’ve also taken some time to step away from\nthe screen and explore new surroundings. I’ve traveled to Maine twice in the\nlast few months (once in November, and again in January) to spend time with my\nnew girlfriend.</p>\n<p>Having grown up in Arizona, I’m not exactly used to the cold, but I’ve been\nenjoying the experience. The East Coast has a fascinating history, and the\nsnow-covered landscapes have been absolutely beautiful.</p>\n<h2>AgapeVerse</h2>\n<p>When I set out to build <strong>AgapeVerse</strong>, my main goals were to create an app with\na paid subscription model and leverage LLMs for content generation. My\ngirlfriend’s deep emotional connection to written words inspired me to focus on\ngenerating &quot;love&quot; poems.</p>\n<p>I originally built the app using <strong>SvelteKit</strong> and <strong>Cloudflare</strong>, but after\nDeno 2’s release, I migrated to <strong>Deno Fresh</strong> and <strong>Deno Deploy</strong>, using <strong>Deno\nSaaSKit</strong> to bootstrap the project. Cloudflare still plays a role—I use it for\nthe <strong>AI Gateway</strong>, <strong>Workers AI</strong> (which powers the free poems), and the\n<strong>OpenAI API</strong> (which enables advanced poem generation, including features like\nacrostic poems where a hidden message is spelled out in the first letter of each\nsentence).</p>\n<h2>The Evolution of *Space: From Digital to Physical</h2>\n<p>One of my biggest aspirations this year is to transform *Space from a digital\ncoworking community on Discord into a real-world space—a physical hub for\ncollaboration, creativity, and mutual support. The vision is to establish a\nspace that not only fosters innovation but also provides a safe haven for those\nin need, all while being governed by a <strong>DAO (Decentralized Autonomous\nOrganization)</strong>. This won’t happen overnight, and I won’t release ownership\nuntil certain conditions are met, but the groundwork is being laid.</p>\n<p>The plan is to:</p>\n<ul>\n<li><strong>Acquire real estate</strong> that serves as a communal living and working space.</li>\n<li><strong>Govern the space through a DAO</strong>, where members earn voting power through\ncontributions.</li>\n<li><strong>Provide resources for creators, entrepreneurs, and those in need</strong>,\ncombining coworking with elements of a supportive, growth-focused community.</li>\n</ul>\n<p>This journey is still in its early stages, but I’m excited to see how it unfolds\nand how it can reshape the way people live, work, and support each other.</p>\n<h2>Looking Ahead</h2>\n<p>The past year and a half have been a whirlwind of learning, contributing, and\nplanning for the future. Between mastering new technologies, working on\nopen-source projects, spending time in Maine, and setting the groundwork for\n*Space’s next chapter, I’ve been fortunate to experience both personal and\nprofessional growth.</p>\n<p><a href=\"https://agapeverse.app\">AgapeVerse</a> is live and available for anyone to use,\nand I’m looking forward to continuing to expand its features while ramping up\nmarketing efforts.</p>\n<p>As *Space continues to develop, I look forward to bringing more people into this\nvision, refining the DAO governance model, and eventually establishing a\nphysical location where ideas can flourish and people can thrive.</p>\n<p>If you’re interested in <strong>SvelteKit, Deno, DAOs, or community-driven spaces</strong>,\nlet’s connect—there’s a lot more ahead!</p>\n<hr>\n<p>Want to stay updated on the journey? Check it out:</p>\n<ul>\n<li><strong><a href=\"https://starspace.group\">starspace.group</a></strong></li>\n<li><strong><a href=\"https://agapeverse.app\">AgapeVerse.app</a></strong></li>\n</ul>\n","featured_image":"","category":"update","read_time":4}', NULL, 'Reflecting on a year and a half of learning SvelteKit and Deno, contributing to Deno Docs, spending time in Maine, and planning the future of *Space.', NULL, NULL, '2025-01-28', '2025-01-28', '2025-01-28'
FROM content_types ct
WHERE ct.slug = 'blog'
	AND NOT EXISTS (
		SELECT 1 FROM content_items ci WHERE ci.content_type_id = ct.id AND ci.slug = '2024-2025-progress-and-future-plans'
	);

-- fixing-computers-by-threating-disassembly
INSERT INTO content_items (id, content_type_id, slug, title, status, fields, seo_title, seo_description, seo_image, author_id, published_at, created_at, updated_at)
SELECT 'import-blog-fixing-computers-by-threating-disassembly', ct.id, 'fixing-computers-by-threating-disassembly', 'The Mysterious Windows 11 Restart Issue - Can Threatening Teardown Fix a Computer? 😂', 'published', '{"excerpt":"Few things are more frustrating than a computer that randomly restarts for no clear reason, especially when you''re in the middle of work (or a good movie). This Windows 11 machine seemed cursed—no error messages, no overheating, nothing super obvious in the event logs, just abrupt, unexplained rebo…","body":"<blockquote>\n<p>[!WARNING]<br>I am not a pro troubleshooter, I have a good track record and I have provided\ntech support and computer services professionally in the past however, my\nprocess is not perfect and should not be interpreted as guidance nor advice!</p>\n</blockquote>\n<h2>The Problem: Random Restarts with No Clear Cause</h2>\n<p>A Windows 11 computer I was working with started exhibiting a frustrating issue:\nintermittent restarts with no obvious trigger. There was no blue screen, no\nerror messages—just an unexpected reboot at seemingly random intervals.</p>\n<p>At first, I suspected overheating, but temperatures looked fine. Then I checked\nevent logs, which provided nothing conclusive. Next, I ran memory diagnostics,\nstress tests, and even a PSU check. Everything seemed normal, yet the problem\npersisted.</p>\n<h2>The Suspect: GPU Drivers</h2>\n<p>Using <strong>Event Viewer</strong> I started logging every shutdown event\n(<code>1074,19,41,1001,7045</code>) then used <strong>WinDbgX</strong> to open the <code>.dump</code> file logged\nwhen the system was rebooting. I traced the issue to the <strong>NVIDIA GPU driver</strong>\n(<code>FAILURE_BUCKET_ID:  0x116_IMAGE_nvlddmkm.sys</code>).</p>\n<p>However, even after using <strong>DDU (Display Driver Uninstaller)</strong> to completely\nremove the drivers and then installing only the latest clean drivers directly\nfrom NVIDIA, the problem persisted. In an attempt to rule out software\ncorruption, I even <strong>reinstalled Windows 11 using the Settings app</strong>.</p>\n<p>For reference the issue that appeared in Event Viewer:\n<code>The computer has rebooted from a bugcheck.  The bugcheck was: 0x00000116</code></p>\n<h2>The Joke Part of This Post</h2>\n<p>During this whole process I did what any normal person does: I tweeted about it.</p>\n<p>Over the course of a few hours, I live-tweeted my troubleshooting process,\nincluding using Event Viewer and WinDbgX to pinpoint the issue, running DDU to\nreinstall clean NVIDIA drivers, and even reinstalling Windows 11.</p>\n<p>After downgrading the GPU driver I tweeted that my <strong>final next step</strong> if the\nissue persisted would be: taking the computer apart to reseat power connectors,\nthe GPU, and RAM, checking the power supply, and replacing the power cable if\nnecessary.</p>\n<p>Now several hours after that tweet, the system is still running fine.. Did the\ndriver downgrade fix it or did the threat of being disassembled scare the\nmachine into behaving? 😆</p>\n<p><strong>Update to this stupid joke: This didn&#39;t fix anything lol</strong></p>\n<h2>The Resolution (Mostly Miserable Failed Attempts)</h2>\n<p>So far, the computer has remained stable. Whether it was truly the driver\ndowngrade or some cosmic response to my public proclamation, I may never know.\nBut one thing’s certain—sometimes, fixing tech problems involves a mix of\nlogical troubleshooting and a little bit of superstition.</p>\n<h3>Update (2026-02-12): The following day...</h3>\n<p>The computer was left on overnight (using Power Toys Awake), and I woke up to\nfind that the system was still running fine. I&#39;m looking forward to getting more\nwork done without the hassle of random reboots. I&#39;ll add another update to this\npost if this problem comes up again, otherwise assume that regardless of if it\nwas the driver downgrade or the computer&#39;s fear of a screwdriver: the issue is\nresolved. 😊 <strong>The issue was not resolved at this point.</strong></p>\n<h3>Update (2025-02-15): The following week...</h3>\n<p>The computer did reboot randomly on February 13th while Glenda and I were\nwatching Secondhand Lions. I checked in the Event Viewer and it was the same\ncrash: <code>The bugcheck was: 0x00000116</code>.</p>\n<p>Should I try to change the driver again, or should I follow up on my promise to\ntake the computer apart?</p>\n<p>The computer hasn&#39;t rebooted a second time since then, I had to look up the\nEvent Viewer text from this blog post because apparently the Events Viewer\nhistory didn&#39;t show what I remember.</p>\n<p>Anyway I said I would post an update here if the problem came up again, so I&#39;m\ndoing that.</p>\n<p>I&#39;ll add another update to this post at some point to let you know how I\ncontinue to diagnose and solve this problem. I have consdered and would like to\navoid contacting NVidia and Microsoft directly. My real wish is that this issue\nisn&#39;t coming from a hardware based problem.</p>\n<p>My decision now is whether to try changing to yet another version of the GPU\ndriver, or to <em>actually</em> take the computer apart (so it knows it wasn&#39;t an empty\nthreat). 😊</p>\n<p>Either way I&#39;ll have to leave another update here and once I&#39;ve taken some\naction then I will do that.</p>\n<h3>Update (2025-02-21): Trying other drivers:</h3>\n<p>So... I had tried the older driver for a while and while things were certainly\nbetter I was still getting random reboots with the same crash.</p>\n<p>I went to go install another (even older) version of the NVidia driver when I\nnoticed that there was actually a <strong>newer</strong> driver released that day (yesterday\nthe 20th). I tried installing that driver and in no time the problem returned in\nfull force. I even tried installing (again) the latest Studio Driver but the\nproblem persisted. One thing I did notice is that the Game Ready driver causes a\nslightly different version of the issue (after the crash the computer reboots\nand the monitor&#39;s no longer work until a second manual reboot, where on the\nStudio Driver the computer reboots but the monitors still work).</p>\n<p>I&#39;m currently installing the oldest version of the Studio Driver (555.99) and\nwe&#39;ll see where that leads. If the problem persists I&#39;ll probably try other\nversions. In any case I should still open the case and at least do some due\ndiligence like reseating RAM (even in a different port).</p>\n<p>More updates to come no matter what.</p>\n<h3>Update (2025-02-27): Discord and Realtek</h3>\n<p>I finally ran into a situation where the computer was rebooting on its own\nquickly; every time I opened a voice call on Discord and turned on my camera\n(still after minutes of that).</p>\n<p>I reinstalled Discord which fixed the problem, temporarily again.</p>\n<p>Today I uninstalled several applications including the Realtek audio driver.</p>\n<p>At that point I also uninstalled Discord and removed the local files recommended\nby their documentation:\n<a href=\"https://support.discord.com/hc/en-us/articles/115004307527--Windows-Corrupt-Installation\">https://support.discord.com/hc/en-us/articles/115004307527--Windows-Corrupt-Installation</a></p>\n<p>After rebooting and running the system without any reboots I installed Discord\nusing the Microsoft Store instead of from the website.</p>\n<h3>Update (2025-03-01): Almost fixed?</h3>\n<p>I thought I had this fixed, went over 72 hours without a reboot. Then out of\nseemingly nowhere we&#39;re back to getting random reboots.</p>\n<p>What did I do that I hoped had fixed it? Removed the Realtek audio driver and/or\ndoing a clean install of Discord and reinstalling from the Windows Store\n(instead of from the Discord website).</p>\n<p>I was so happy to finally be rid of this problem then, here we go again back to\nrandom reboots without any indication as to why.</p>\n<p>Right before the first new random reboot I had opened the Logi Tune app, so I\nimmediate uninstalled it (and rebooted after). The computer has unfortunately\nrebooted since then.</p>\n<p>The last thing I&#39;ve done so far is to uninstall VS Code using the Windows\n<code>Add or remove programs</code> system settings panel then, reinstalling it from the\nMicrosoft Store app.</p>\n<p>I think at this point I&#39;m left with two choices: Reinstall Windows from scratch\nor continue tracing down a likely software issue. It could be that this is\nactually a hardware issue but given the changes in behavior after changing the\nsoftware in the many ways I have so far: My theory is that there is some kind of\ncorruption on on the hard drive, in the Windows installation (or something deep\nenough that it&#39;s causing issues with newly installed apps). I could try the\n<strong>reinstall Windows 11 using the Settings app</strong> again I suppose.</p>\n<h3>Recap of attempted troubleshooting steps to this point:</h3>\n<ul>\n<li>Reinstalling Windows from Settings App (without deleting apps)</li>\n<li>Downgrading and upgrading NVIDIA GPU drivers (multiple versions)</li>\n<li>Using DDU (Display Driver Uninstaller) for clean GPU driver installs</li>\n<li>Removing Realtek audio drivers</li>\n<li>Reinstalling Discord (both from the website and Microsoft Store)</li>\n<li>Checking Event Viewer and analyzing crash dumps with WinDbgX</li>\n<li>Uninstalling VS Code and reinstalling from the Microsoft Store</li>\n<li>Uninstalling Logi Tune</li>\n<li>Run Memtest (from bootable image)</li>\n</ul>\n<h3>Facts of the case:</h3>\n<ul>\n<li>Apps I installed (and their configs etc.):<ul>\n<li>Visual Studio Code installed<ul>\n<li>Using Continue<ul>\n<li>Ollama</li>\n</ul>\n</li>\n</ul>\n</li>\n<li>Microsoft PowerToys installed<ul>\n<li>PowerToys Awake used entire time</li>\n</ul>\n</li>\n<li>Docker</li>\n<li>Asana</li>\n<li>Ollama</li>\n<li>Krita</li>\n<li>Logi Tune</li>\n<li>Logi Options+</li>\n</ul>\n</li>\n<li>Apps likely already installed:<ul>\n<li>Discord</li>\n<li>Spotify</li>\n<li>Chrome</li>\n</ul>\n</li>\n<li>Apps definitely already installed:<ul>\n<li>Steam</li>\n</ul>\n</li>\n<li>Apps/drivers reinstalled by me:<ul>\n<li>NVIDIA 3060 driver<ul>\n<li>Newest, oldest, and a few others<ul>\n<li>Game Ready and Studio Driver<ul>\n<li>with and without optional software and drivers</li>\n</ul>\n</li>\n</ul>\n</li>\n</ul>\n</li>\n<li>Discord</li>\n<li>Chrome</li>\n<li>Visual Studio Code</li>\n</ul>\n</li>\n<li>Apps installed by me then uninstalled without reinstall:<ul>\n<li>Logi Tune</li>\n</ul>\n</li>\n</ul>\n<h3>Options Being Considered</h3>\n<ul>\n<li>Full Windows reinstall</li>\n</ul>\n<h3>Update (2025-03-01): Turning off AUTO in BIOS PCIe Settings</h3>\n<p>Well, I reinstalled Windows 11 (using the Reset PC option in the Settings app).\nIt didn&#39;t take long before another random reboot happened again, and again I saw\nthe same Error message in the Event Viewer.</p>\n<p>This time I looked a little more into the Event Viewer logs and saw a bunch of\nother event messages, a bunch of which said something about the PCI Express Root\nPort.</p>\n<pre><code>A corrected hardware error has occurred.\n\nComponent: PCI Express Root Port\nError Source: Advanced Error Reporting (PCI Express)\n\nPrimary Bus:Device:Function: 0x0:0x1:0x0\nSecondary Bus:Device:Function: 0x0:0x0:0x0\nPrimary Device Name:PCI\\VEN_8086&amp;DEV_4C01&amp;SUBSYS_373317AA&amp;REV_01\nSecondary Device Name:\n</code></pre>\n<p>I found some posts about people experiencing and fixing problems related to\nthese kinds of log messages and the fix that worked for many was to switch from\nthe <code>Auto</code> PCIe version setting to manually selecting PCIe 3...</p>\n<p>I tried the same on this machine and haven&#39;t had any reboots since, although I\ndid just notice that I&#39;m still seeing that message over and over in the Event\nViewer. I&#39;ll be digging into that more later but for now I&#39;m just hoping that\nthe PC doesn&#39;t randomly crash again.</p>\n<p>Here&#39;s the related post that I saw:</p>\n<ul>\n<li><a href=\"https://www.reddit.com/r/buildapc/comments/tpicq0/whea_logger_id_event_17/\">https://www.reddit.com/r/buildapc/comments/tpicq0/whea_logger_id_event_17/</a></li>\n</ul>\n<h3>Update (2025-03-19): Setting NVIDIA Power Management Mode to Prefer Maximum Performance</h3>\n<p><img src=\"/fix-busreset-gpt-screenshot.png\" alt=\"Chat GPT Screenshot\"></p>\n<p>I found another more specific Event Viewer entry\n<code>BusReset TDR occurred on GPUID:100</code> and put it into ChatGPT (something I&#39;ve\nbeen doing a lot recently lol) and I was reminded to try the following:</p>\n<pre><code>4. Adjust Power Settings\nNVIDIA drivers sometimes have issues with power management settings, especially on desktop systems.\n\nRight-click on the desktop and choose NVIDIA Control Panel.\nUnder Manage 3D Settings, look for the Power Management Mode setting.\nChange it from Optimal Power to Prefer Maximum Performance.\n</code></pre>\n<p>This was back on the 13th (6 days ago) and the computer has not rebooted\nunexpectedly since then.</p>\n<h2>Solution?: Setting NVIDIA Power Management Mode to Prefer Maximum Performance</h2>\n<p>I can finally say the computer has not rebooted unexpectedly for more than a\ncouple of weeks!</p>\n<p>Here is a reminder of the last setting I changed:</p>\n<ul>\n<li><code>NVIDIA Control Panel</code>:<ul>\n<li><code>Manage 3D Settings</code>:<ul>\n<li><code>Power Management Mode</code> = <code>Prefer Maximum Performance</code></li>\n</ul>\n</li>\n</ul>\n</li>\n</ul>\n<p>I would like to spend some time to switch back to the original bios setting and\nsee if the problem persists. When I do then I&#39;ll post a final update here.</p>\n<h2>Conclusion</h2>\n<p>I&#39;m happy to say the computer has not rebooted unexpectedly for more than a\ncouple of weeks but until I know exactly why this was happening I&#39;m not sure if\nthis is a permanent solution or just a temporary one. Even if it is a permanent\nsolution the nerd in me must know WHY this happened in the first place.</p>\n<p>Future steps:</p>\n<ul>\n<li> Switch back to the original bios setting (<code>PCIe</code>: <code>Auto</code>).</li>\n<li> Update the NVIDIA video driver to latest version (studio and game ready).</li>\n<li> Update all other software and drivers (including OS).</li>\n</ul>\n<h2>Screenshots</h2>\n<div class=\"flex flex-col space-y-2 space-x-2=\">\n  <img src=\"/win11-pc-screenshot-event-viewer-restarts.jpg\" alt=\"Win11 PC Screenshot: Event Viewer Restarts\" width=\"600\" height=\"450\" />\n  <img src=\"/win11-pc-screenshot-hwinfo-taskmanager.jpg\" alt=\"Win11 PC Screenshot: HWInfo Task Manager\" width=\"600\" height=\"450\" />\n</div>","featured_image":"","category":"update","read_time":11}', NULL, 'Few things are more frustrating than a computer that randomly restarts for no clear reason, especially when you''re in the middle of work (or a good movie). This Windows 11 machine seemed cursed—no error messages, no overheating, nothing super obvious in the event logs, just abrupt, unexplained rebo…', NULL, NULL, '2025-02-11T08:30:00Z', '2025-02-11T08:30:00Z', '2025-02-11T08:30:00Z'
FROM content_types ct
WHERE ct.slug = 'blog'
	AND NOT EXISTS (
		SELECT 1 FROM content_items ci WHERE ci.content_type_id = ct.id AND ci.slug = 'fixing-computers-by-threating-disassembly'
	);

-- git-global-ignore-dot-notes
INSERT INTO content_items (id, content_type_id, slug, title, status, fields, seo_title, seo_description, seo_image, author_id, published_at, created_at, updated_at)
SELECT 'import-blog-git-global-ignore-dot-notes', ct.id, 'git-global-ignore-dot-notes', 'A Simple Notes File in Every Project, Ignored by Git Globally', 'published', '{"excerpt":"Learn how to set up a global ignore environment notes file for your project.","body":"A Simple Notes File in Every Project, Ignored by Git Globally\n<p>When working on code projects it&#39;s common and important to have a place where\nyou can keep track of important information or notes. Whether it&#39;s for personal\nprojects, team collaboration, or just to remember something specific, having a\ncentralized location for these notes is invaluable.</p>\n<p>I have used several centralized notes applications, up to this point my basic\nroutine was to use Asana for larger projects and Google Docs for smaller one off\nnotes. This is not an impressive solution for a modern software engineer by any\nmeans. My hip friends are using custom emacs and vim setups or at least some\ncentral text based tool like Obsidian. I never ended up on Obsidian because I\nwas happy enough with what I had and always avoid paying over time for things if\nI can.</p>\n<p>I&#39;ve known that I needed a better solution and randomly this idea came to me. I\nhaven&#39;t yet researched it (I imagine this is far from a new idea) but... What I\nended up doing recently I feel is worth sharing in case you haven&#39;t considered\nit.</p>\n<h2>Setting Up a Git Global Ignore with a Standard Notes File Name</h2>\n<p>Some may not know this (even though I did know I never used it): You can set up\na global <code>.gitignore</code> file that applies to all repositories on that machine.</p>\n<p>I created a file <code>~/.gitignore</code> with the following content:</p>\n<pre><code class=\"language-ignore\">**/.notes.md\n</code></pre>\n<p>I then followed <a href=\"https://stackoverflow.com/a/7335487/2446026\">this Stack\nOverflow post with commands to config git to use this global <code>.gitignore</code></a>.</p>\n<p>For me on Windows PowerShell it was:</p>\n<pre><code>git config --global core.excludesFile &quot;$Env:USERPROFILE\\.gitignore&quot;\n</code></pre>\n<p>I created the .gitignore in the right place by using the following command in\nWindows PowerShell:</p>\n<pre><code>code $Env:USERPROFILE\\.gitignore\n</code></pre>\n<p>Note that this works by opening the new file in VS Code and from there you&#39;ll\nneed to add the <code>*/.notes.md</code> entry and save the file.</p>\n<p>Now when I create a note file called .env.notes.md in any project, Git will\nignore it by default!</p>\n<h3>Screenshot(s)</h3>\n<img src=\"/.notes.md.screenshot.jpg\" alt=\"Screenshot of todos file in VS Code\" width=\"528\" height=\"400\" height=\"450\" />","featured_image":"","category":"update","read_time":2}', NULL, 'Learn how to set up a global ignore environment notes file for your project.', NULL, NULL, '2025-02-17T14:00:00Z', '2025-02-17T14:00:00Z', '2025-02-17T14:00:00Z'
FROM content_types ct
WHERE ct.slug = 'blog'
	AND NOT EXISTS (
		SELECT 1 FROM content_items ci WHERE ci.content_type_id = ct.id AND ci.slug = 'git-global-ignore-dot-notes'
	);
INSERT INTO content_tags (id, content_type_id, name, slug)
SELECT 'import-tag-git', ct.id, 'git', 'git'
FROM content_types ct
